import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Pluggable Module Composition","description":"","frontmatter":{"title":"Pluggable Module Composition","type":"adr","date":"2026-08-24T00:00:00.000Z","status":"proposed","status_note":"Proposed"},"headers":[],"relativePath":"handl/project/adrs/0028-pluggable-module-composition.md","filePath":"vendored/handl/project/adrs/0028-pluggable-module-composition.md"}`),a={name:`handl/project/adrs/0028-pluggable-module-composition.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pluggable-module-composition" tabindex="-1">Pluggable Module Composition <a class="header-anchor" href="#pluggable-module-composition" aria-label="Permalink to “Pluggable Module Composition”">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to “Context”">​</a></h2><p>The handl compiler already keeps lexing, parsing, resolving, typechecking, and formatting in separate crates. The existing <code>ParseStage</code> dispatches to a <code>Frontend</code> using only the <code>Source.format</code> string, and <code>FileResolver</code> derives that format from the file extension. This is the beginning of a multi-language import pipeline, but it is hard-coded: the <code>frontend_for(format)</code> map is a static match, and the <code>Dialect</code> trait represents a single bundled syntax.</p><p>Because the pipeline is decoupled, the module system can already import files with different lexers, parsers, and syntaxes. We want to make this first-class: each handl module should declare which kits and plugins it uses, and the compiler should compose the correct pipeline for that module.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>We will replace the static <code>frontend_for(format)</code> mechanism and the monolithic <code>Dialect</code> trait with a <strong>pluggable, per-module composition</strong> system.</p><h3 id="module-toml-manifest" tabindex="-1"><code>module.toml</code> manifest <a class="header-anchor" href="#module-toml-manifest" aria-label="Permalink to “module.toml manifest”">​</a></h3><p>Every module folder may contain a <code>module.toml</code> manifest. The manifest describes the language kit and/or the per-stage plugins used by that module. Nested modules can have their own <code>module.toml</code>, so a project can mix syntaxes and toolchains.</p><p>Example:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">[</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">language</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">kit </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-kit-canonical</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">lexer </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-lexer-multi-line-strings</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">parser </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-parser-type-annotations</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-dark:#888888;--shiki-light:#24292E;">[</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#6F42C1;">passes</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">typecheck </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-typecheck-core</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-typecheck-import</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">format </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-format-canonical</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span></code></pre></div><h3 id="naming-convention" tabindex="-1">Naming convention <a class="header-anchor" href="#naming-convention" aria-label="Permalink to “Naming convention”">​</a></h3><p>All kits and plugins are named with the <code>handl-</code> prefix to avoid conflicts with external packages and to make discovery deterministic:</p><ul><li>Kits: <code>handl-kit-*</code></li><li>Lexers: <code>handl-lexer-*</code></li><li>Parsers: <code>handl-parser-*</code></li><li>Typecheckers: <code>handl-typecheck-*</code></li><li>Formatters: <code>handl-format-*</code></li><li>Generic passes: <code>handl-pass-*</code></li><li>Multi-pass plugins: <code>handl-plugin-*</code></li></ul><h3 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to “Composer”">​</a></h3><p>A new <code>Composer</code> takes the <code>module.toml</code> configuration, reads each plugin&#39;s pass declarations, and assembles the right <code>(lexer, parser, passes...)</code> for the module. It also validates that the configured passes are coherent: every required pass has an implementing plugin and no conflicting duplicate is present. This replaces the current <code>handl_frontend::frontend_for</code> static map. The <code>ParseStage</code> (and later stages) will invoke the <code>Composer</code> instead of <code>frontend_for(format)</code>.</p><h3 id="pluggable-passes" tabindex="-1">Pluggable passes <a class="header-anchor" href="#pluggable-passes" aria-label="Permalink to “Pluggable passes”">​</a></h3><p>All compiler passes become pluggable:</p><ul><li><code>lexer</code></li><li><code>parser</code></li><li><code>resolve</code></li><li><code>typecheck</code></li><li><code>format</code></li><li><code>generate</code></li></ul><p>Each pass is a plugin implementing a common <code>Pass</code> trait. <code>compiler-pass-parse</code>, <code>compiler-pass-typecheck</code>, etc. become thin orchestrators that run the configured plugins in order.</p><h3 id="plugin-pass-declarations" tabindex="-1">Plugin pass declarations <a class="header-anchor" href="#plugin-pass-declarations" aria-label="Permalink to “Plugin pass declarations”">​</a></h3><p>Every plugin declares the passes it implements. A single plugin may implement multiple passes, and those declarations live in plugin metadata rather than the user-facing manifest.</p><p>Example plugin metadata:</p><div class="language-toml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">name </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">handl-plugin-single-comments</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span></span>
<span class="line"><span style="--shiki-dark:#FFFFFF;--shiki-light:#24292E;">passes </span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">=</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;"> [</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">lexer</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">typecheck</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">,</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#FFFFFF;--shiki-light:#032F62;">format</span><span style="--shiki-dark:#888888;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#888888;--shiki-light:#24292E;">]</span></span></code></pre></div><p>The <code>Composer</code> expands each plugin into its declared pass slots. For example, <code>handl-plugin-single-comments</code> would contribute to the <code>lexer</code>, <code>typecheck</code>, and <code>format</code> pipelines for the module. A manifest may still list dedicated stage plugins such as <code>handl-lexer-*</code> or <code>handl-format-*</code> to override or extend a specific pass.</p><p>The <code>Composer</code> validates that every pass required by the manifest has at least one implementing plugin and detects conflicts or duplicate implementations before the pipeline runs.</p><h3 id="ast-strategy" tabindex="-1">AST strategy <a class="header-anchor" href="#ast-strategy" aria-label="Permalink to “AST strategy”">​</a></h3><p>Plugins may produce different ASTs. To keep the rest of the pipeline tractable, the recommended default is a <strong>lower</strong> or <strong>canonicalize</strong> pass that turns a plugin-specific AST into a shared canonical IR. Later stages (resolve, typecheck, generate) then operate on the canonical IR. If a module opts out of lowering, it must also provide a complete, AST-specific pass chain.</p><h3 id="resolver-integration" tabindex="-1">Resolver integration <a class="header-anchor" href="#resolver-integration" aria-label="Permalink to “Resolver integration”">​</a></h3><p><code>FileResolver</code>, and the virtual/HTTP/Git resolvers by extension, will discover <code>module.toml</code> when resolving a module path. If the resolved path is a directory, the resolver reads the manifest and loads the declared entry file. The resolved <code>ModuleConfig</code> travels through <code>ResolvedModule</code> → <code>Source</code> → the <code>Composer</code>.</p><h3 id="dialect-trait" tabindex="-1">Dialect trait <a class="header-anchor" href="#dialect-trait" aria-label="Permalink to “Dialect trait”">​</a></h3><p>The existing <code>handl-dialect</code> <code>Dialect</code> trait and canonical dialect crate are deprecated in favor of this plugin model. Syntax, schema vocabulary, and special keys become <code>handl-lexer-*</code>, <code>handl-parser-*</code>, and <code>handl-pass-*</code> plugins rather than a single bundled dialect.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>Source.format</code> and <code>frontend_for(format)</code> will be removed in favor of <code>Source.module_config</code> and <code>Composer::compose(config)</code>.</li><li><code>handl_frontend</code> is effectively obsolete in its current form; it will be replaced by or evolve into a <code>Composer</code> crate.</li><li><code>handl-dialect</code> and <code>handl-dialect-canonical</code> will be removed or significantly reduced.</li><li>Every compiler pass crate becomes a plugin host rather than a single implementation.</li><li>A new plugin registry is required to map <code>handl-*</code> names to concrete trait implementors.</li><li><code>module-resolver-*</code> crates must be updated to read <code>module.toml</code> and pass <code>ModuleConfig</code>.</li><li>Tests will move from “this syntax” vs “that syntax” to “this kit/plugins combination” vs “that kit/plugins combination”.</li><li>Nested modules can mix syntaxes, e.g. a root project in <code>handl-kit-canonical</code> importing a JSON-config sub-module.</li></ul>`,33)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};